## ---- 01: The Shared Part IV Pool  (qmd line 300) -------------------------------------

library(oasr)

pool_assets <- oasr::sample_abs_data        # 12 loans, with io_strip
deal_structure <- oasr::sample_deal_structure  # 3 sequential-pay bonds

# Simulated rate paths (Chapter 6); lambda is per year (Chapter 2)
dns_params <- list(
  params = list(kappa = c(0.3, 0.5, 0.8),
                theta = c(0.04, -0.01, 0.01),
                sigma = c(0.010, 0.012, 0.015)),
  initial_factors = c(0.035, -0.015, 0.005),
  lambda = 0.7308
)
rate_paths <- simulate_rates(dns_params, n_paths = 100,
                             n_periods = 360, seed = 42)

# Credit vectors and loan-level cashflows (Parts II and III)
prepay_mod <- prepayment_model(type = "cpr_cdr", base_cpr = 0.06,
                               base_cdr = 0.01, recovery_rate = 0.65)
credit_v  <- calculate_credit_vectors(pool_assets, rate_paths, prepay_mod)
ref_rates <- extract_reference_rates(rate_paths, reference_key = "10")
asset_cf  <- project_cashflows(pool_assets, credit_v,
                               reference_rates = ref_rates)

# Bond-level cashflows: one [period x component x bond] array per path,
# with component 5 the total (see cashflow_components("bond"))
pool_cf <- aggregate_cashflows(asset_cf, pool_assets, deal_structure,
                               reference_rates = ref_rates)

# Solved OAS at a par market price
oas_result <- calculate_oas(pool_assets, rate_paths, prepay_mod,
                            market_price = 100, deal_structure = deal_structure,
                            verbose = FALSE)
oas_result$oas            # ~221 bps


## ---- 02: Path-Level NPV via `oasr::calculate_present_value`  (qmd line 339) ----------

library(oasr)

# pool_cf and rate_paths come from the shared setup above
pv <- calculate_present_value(
  cashflows  = pool_cf,
  rate_paths = rate_paths,
  oas        = 120,           # OAS in basis points
  reference_key = "10",
  asset_level = FALSE,
  total_idx  = 5              # bond-level total-cashflow component
)

pv$mean_pvs                   # mean PV per bond
pv$pv_stats                   # per-bond PV mean, sd, min, max
path_npv <- rowSums(pv$present_values)   # vector of path-level pool NPVs


## ---- 03: Confidence Intervals  (qmd line 359) ----------------------------------------

# Helper: 95% CI from the path-level NPV vector
ci_95 <- function(path_pv) {
  m  <- mean(path_pv)
  se <- sd(path_pv) / sqrt(length(path_pv))
  m + c(-1.96, 1.96) * se
}
ci_95(path_npv)


## ---- 04: Convergence Diagnostic (User Helper)  (qmd line 371) ------------------------

library(ggplot2)
convergence_plot <- function(path_pv) {
  df <- data.frame(
    path = seq_along(path_pv),
    mean = cumsum(path_pv) / seq_along(path_pv),
    se   = sapply(seq_along(path_pv), function(p)
      sd(path_pv[1:p]) / sqrt(p))
  )
  ggplot(df, aes(path, mean)) +
    geom_ribbon(aes(ymin = mean - 1.96 * se,
                    ymax = mean + 1.96 * se),
                fill = "grey85") +
    geom_line() +
    labs(x = "Path count", y = "Running fair value") +
    theme_minimal()
}
convergence_plot(path_npv)


## ---- 05: Antithetic Variates (User Helper)  (qmd line 393) ---------------------------

# Helper: pair-mean variance reduction over independent + antithetic shocks
mc_antithetic <- function(pv_pos, pv_neg) {
  v_pair <- 0.5 * (pv_pos + pv_neg)
  list(fair_value = mean(v_pair),
       se         = sd(v_pair) / sqrt(length(v_pair)))
}


## ---- 06: Control Variates (User Helper)  (qmd line 404) ------------------------------

mc_control <- function(npv, control, control_mean) {
  beta <- cov(npv, control) / var(control)
  npv_cv <- npv - beta * (control - control_mean)
  list(fair_value = mean(npv_cv),
       se         = sd(npv_cv) / sqrt(length(npv_cv)))
}


## ---- 07: Quasi-Monte Carlo  (qmd line 415) -------------------------------------------

library(randtoolbox)

n_paths <- 1024
n_dim   <- 360 * 3   # 360 months × 3 factors
sobol_pts <- sobol(n_paths, dim = n_dim)
# random shift (mod 1) stands in for the digital shift
shift      <- runif(n_dim)
sobol_pts  <- sweep(sobol_pts, 2, shift, "+") %% 1
shocks_qmc <- qnorm(sobol_pts)
