## ---- 09: Pathwise Greek (User Helper)  (qmd line 446) --------------------------------

# Pathwise duration estimator from path-level cashflow tensor
pathwise_duration <- function(cf_matrix, rate_matrix, oas, dt = 1/12) {
  disc  <- exp(-t(apply(rate_matrix + oas, 1, cumsum)) * dt)
  t_vec <- seq_len(ncol(cf_matrix)) * dt
  num <- mean(rowSums(cf_matrix * disc * t_vec))
  den <- mean(rowSums(cf_matrix * disc))
  -num / den
}


